<script setup>
import {ref,computed} from 'vue'
import App from './App.vue'
import DecisionLab from './DecisionLab.vue'
import ReportWorkspace from './ReportWorkspace.vue'
const reportContext=ref({})
function openReport(context){reportContext.value=context;tab.value='出海分析报告'}
const user=ref(null),account=ref(''),password=ref(''),error=ref(''),tab=ref('业务工作台'),show=ref(false)
const accounts=[{account:'enterprise',password:'Demo123!',role:'企业用户',name:'企业探索空间'},{account:'analyst',password:'Demo123!',role:'研究分析员',name:'产业研究空间'},{account:'admin',password:'Demo123!',role:'管理员',name:'平台管理空间'}]
const tabs=computed(()=>['业务工作台','决策实验室','出海分析报告','AI 研判草稿',...(user.value?.role==='企业用户'?[]:['资料审核']),...(user.value?.role==='管理员'?['账号与角色']:[])])
const target=ref('泰国'),product=ref(''),focus=ref('市场准入与产品认证'),report=ref(null),reviewed=ref(false)
function login(){const found=accounts.find(a=>a.account===account.value.trim()&&a.password===password.value);if(!found){error.value='账号或密码不正确，请使用下方演示账号。';return}user.value={role:found.role,name:found.name,account:found.account};password.value='';error.value=''}
function logout(){user.value=null;account.value='';password.value='';tab.value='业务工作台';report.value=null;reviewed.value=false}
function generate(){if(!product.value.trim())return;report.value={country:target.value,product:product.value.trim(),focus:focus.value,date:new Date().toLocaleString('zh-CN')}}
function download(){const r=report.value;const text=`出海研判草稿（演示模板，非 AI 生成）\n目标市场：${r.country}\n产品：${r.product}\n关注方向：${r.focus}\n生成时间：${r.date}\n\n市场机会：待补充经核验的市场规模、需求和竞争数据。\n合规风险：核验 HS 归类、进口资质、税收、产品认证与标签规则。\n行动建议：收集官方条文，核对生效日期，由业务人员复核后再决策。\n政策来源：尚未接入，所有事项均待核验。`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='market-research-demo.txt';a.click();URL.revokeObjectURL(url)}
</script>
<template>
<div v-if="!user" class="login-screen"><section class="login-story"><div class="login-brand">远航<span>™</span></div><p class="eyebrow">GO GLOBAL, WITH CONFIDENCE.</p><h1>发现新市场。<br>连接新可能。</h1><p>市场洞察、合规筛查与证据驱动的智能研究，<br>在同一个工作空间展开。</p><div class="login-orbit">◎ <span>THAILAND · INDONESIA · VIETNAM</span></div><small>第 1 组 · 产业出海智能服务系统 / 中期原型</small></section><section class="login-form"><span class="prototype">本地演示 · 不提供真实身份认证</span><h2>欢迎回到远航</h2><p>登录你的产业出海工作空间</p><form @submit.prevent="login"><label for="account">账号</label><input id="account" v-model="account" autocomplete="username" required placeholder="请输入账号"><label for="password">密码</label><div class="password-field"><input id="password" v-model="password" :type="show?'text':'password'" autocomplete="current-password" required placeholder="请输入密码"><button type="button" @click="show=!show">{{show?'隐藏':'显示'}}</button></div><p v-if="error" role="alert" class="login-error">{{error}}</p><button class="primary login-submit">登录工作空间 →</button></form><div class="demo-accounts"><strong>中期演示账号</strong><p>统一密码：Demo123!</p><button v-for="a in accounts" @click="account=a.account;password=a.password;error=''">{{a.role}} <code>{{a.account}}</code><span>填入 →</span></button></div><small>角色由演示账号确定。正式角色须由服务器验证并返回，不能由用户自行指定。</small></section></div>
<template v-else><div class="session-bar"><strong>{{user.name}}</strong><span>{{user.account}} · {{user.role}}</span><button @click="logout">退出登录</button></div><div class="workspace-tabs"><button v-for="t in tabs" :class="{chosen:tab===t}" @click="tab=t">{{t}}</button></div><App v-if="tab==='业务工作台'" @open-report="openReport"/><DecisionLab v-else-if="tab==='决策实验室'"/><ReportWorkspace v-else-if="tab==='出海分析报告'" :context="reportContext"/><main v-else class="extension"><p class="eyebrow">RESEARCH WORKSPACE / {{user.role}}</p><template v-if="tab==='AI 研判草稿'"><h1>从一个问题，到一份行动清单。</h1><p class="intro">AI 结合方向：市场比较、政策检索、风险清单与证据引用。当前仅演示模板流程。</p><div class="notice">尚未连接模型或知识库；下方草稿为本地模板，不是 AI 分析结果。</div><div class="two-col"><section class="panel"><h2>研究任务</h2><label>目标市场</label><el-select v-model="target"><el-option v-for="c in ['泰国','印度尼西亚','越南']" :value="c" :label="c"/></el-select><label>产品或业务</label><el-input v-model="product" maxlength="150" placeholder="例如：纯电动乘用车出口"/><label>研究重点</label><el-select v-model="focus"><el-option v-for="f in ['市场准入与产品认证','市场机会与竞争比较','关税与原产地规则']" :value="f" :label="f"/></el-select><button class="primary" :disabled="!product.trim()" @click="generate">生成演示草稿 →</button></section><section class="panel"><h2>证据驱动的研究流程</h2><p v-for="(s,i) in ['明确国家、产品与问题','检索经审核政策与市场数据','附引用生成结构化分析','人工复核后导出报告']">0{{i+1}}　{{s}}</p><small>正式接入后：检索无证据时应停止结论生成，并说明缺失项。</small></section></div><section v-if="report" class="panel result"><h2>{{report.country}} · {{report.product}}</h2><small>{{report.date}} / 演示模板 / {{report.focus}}</small><h3>01 市场机会</h3><p>待补充经核验的市场规模、需求趋势与竞争信息，不据此判断投资收益。</p><h3>02 合规风险</h3><p>需核验 HS 归类、进口主体资质、税收待遇、产品认证、标签及环保要求。</p><h3>03 行动建议</h3><p>收集官方原文 → 核对适用条件与生效时间 → 由业务人员复核 → 形成正式研判。</p><p class="notice">政策来源：尚未接入。所有事项均待核验，无真实模型调用。</p><button class="primary" @click="download">导出草稿 TXT</button></section></template><template v-else-if="tab==='资料审核'"><h1>让每一份依据，都可追溯。</h1><p class="intro">研究人员工作流原型：审核资料的来源、适用范围与更新时间。</p><section class="panel"><h2>示例资料 · 待接入真实文档</h2><p>来源：未提供　生效日期：未核验　状态：{{reviewed?'已标记待补充':'待审核'}}</p><p>演示条目缺少官方出处，不能发布为可信知识。</p><button class="primary" @click="reviewed=true">标记为待补充资料</button><p v-if="reviewed" role="status">本次会话已标记，未写入服务器。</p></section></template><template v-else><h1>账号与角色</h1><p class="intro">演示权限矩阵；真实账号增删和授权需接入服务端。</p><el-table :data="accounts.map(a=>({account:a.account,role:a.role,permission:a.role==='企业用户'?'市场浏览、筛查、问答、草稿':a.role==='研究分析员'?'企业功能、资料审核':'全部演示入口、角色概览'}))"><el-table-column prop="account" label="账号"/><el-table-column prop="role" label="角色"/><el-table-column prop="permission" label="可见功能"/></el-table><p class="notice">前端隐藏入口不构成安全权限控制。服务端须逐个接口校验身份和角色。</p></template></main></template>
</template>
<style>
.login-screen{min-height:100vh;display:grid;grid-template-columns:1.1fr 1fr}.login-story{background:#eef6f6;padding:65px 9%;display:flex;flex-direction:column;justify-content:center}.login-brand{font-size:35px;font-weight:700;margin-bottom:55px}.login-brand span{font-size:14px;color:#129ac5;margin-left:6px}.login-story h1{font-size:48px}.login-story>p:not(.eyebrow){color:#76858a;font-size:14px}.login-orbit{font-size:100px;color:#31a1b9;margin:30px 0}.login-orbit span{font-size:10px;letter-spacing:2px;display:block}.login-form{max-width:470px;width:100%;padding:65px 38px;margin:auto}.login-form h2{font-size:28px;margin:26px 0 10px}.login-form>p{color:#858b92;font-size:13px;margin-bottom:28px}.login-form label,.extension label{display:block;font-size:13px;margin:17px 0 9px}.login-form input{width:100%;border:1px solid #d8dfe2;border-radius:9px;padding:13px;font-size:14px}.password-field{display:flex;position:relative}.password-field input{padding-right:60px}.password-field button{position:absolute;right:10px;top:13px;background:none;border:0;color:#737e86;font-size:12px}.login-submit{width:100%;justify-content:center;margin:24px 0}.login-error{color:#b42b2b;font-size:12px}.demo-accounts{border-top:1px solid #eee;padding:20px 0}.demo-accounts strong{font-size:13px}.demo-accounts p{font-size:12px;color:#838b91}.demo-accounts button{display:flex;gap:16px;width:100%;padding:10px 0;border:0;background:none;text-align:left;font-size:12px}.demo-accounts span{margin-left:auto;color:#1589ac}.session-bar{display:flex;align-items:center;gap:20px;padding:11px 28px;background:#202124;color:white;font-size:12px}.session-bar span{margin-left:auto;color:#ddd}.session-bar button{background:none;border:1px solid #777;color:white;border-radius:15px;padding:5px 12px}.workspace-tabs{display:flex;padding:10px 28px;gap:12px;border-bottom:1px solid #ddd;background:white}.workspace-tabs button{border:0;background:none;padding:9px 15px;font-size:13px;border-radius:18px}.workspace-tabs .chosen{background:#e9f4f8;color:#1685a6}.shell aside{height:calc(100vh - 100px)}.extension{max-width:1150px;padding:30px;margin:auto}.extension .primary{margin-top:22px}.extension .el-input,.extension .el-select{width:100%}@media(max-width:700px){.login-screen{grid-template-columns:1fr}.login-story{padding:28px}.login-brand{margin-bottom:10px}.login-story h1{font-size:30px}.login-orbit{display:none}.login-form{padding:30px}.session-bar{padding:10px;gap:8px}.workspace-tabs{padding:8px;overflow:auto;white-space:nowrap}.extension{padding:20px}.login-story .eyebrow{margin-top:10px}}
</style>
